package codex

import (
	"path/filepath"
	"strconv"
	"strings"

	adapter "github.com/teamva-ai/teamva/node/provider"
)

const codexPermissionProfile = "teamva"

// initialize.userAgent is generated by the native app-server as name/version.
// Older serde servers may silently ignore newer request fields, so their lack
// of an RPC error is NOT proof of support. Refuse before creating any turn.
func codexSupportsExactPermissions(userAgent string) bool {
	fields := strings.Fields(userAgent)
	if len(fields) == 0 {
		return false
	}
	_, version, ok := strings.Cut(fields[0], "/")
	if !ok {
		return false
	}
	parts := strings.Split(version, ".")
	if len(parts) != 3 {
		return false
	}
	major, errMajor := strconv.Atoi(parts[0])
	minor, errMinor := strconv.Atoi(parts[1])
	patch, errPatch := strconv.Atoi(parts[2])
	if errMajor != nil || errMinor != nil || errPatch != nil || major < 0 || minor < 0 || patch < 0 {
		return false
	}
	return major > 0 || (major == 0 && minor >= 163)
}

// Codex 0.163.0's legacy workspaceWrite ALWAYS adds CWD, even with an exact
// writableRoots list. A named filesystem profile instead materializes only the
// supplied runtimeWorkspaceRoots and has no implicit CWD, /tmp or TMPDIR grant.
// Native contract: rust-v0.163.0, commit 83086188ae0614bd882818ff1aa23f3194962012:
// app-server-protocol/src/protocol/v2/{thread,turn}.rs, core/src/config/permissions.rs.
func codexPermissionConfig(readOnlyPaths ...string) map[string]any {
	filesystem := map[string]any{":root": "read", ":workspace_roots": map[string]any{".": "write", ".git": "write"}}
	for _, path := range readOnlyPaths {
		filesystem[filepath.ToSlash(path)] = "read"
	}
	return map[string]any{
		"default_permissions": codexPermissionProfile,
		"permissions": map[string]any{codexPermissionProfile: map[string]any{
			// Codex otherwise adds a default read-only .git carveout even to an
			// explicitly writable root. Only in-root .git is writable: gitdirs
			// outside the business root remain outside this grant.
			"filesystem": filesystem,
			"network":    map[string]any{"enabled": false},
		}},
	}
}

func codexRunWritableRoots(request adapter.RunRequest, repositories []string) []string {
	roots := make([]string, 0, len(repositories)+1)
	if !request.ReadOnly {
		roots = append(roots, repositories...)
	}
	if request.ToolRequestDir != "" {
		roots = append(roots, request.ToolRequestDir)
	}
	return roots // An explicit empty array revokes prior roots on Resume.
}

func codexRunApprovalPolicy(readOnly bool) any {
	if readOnly {
		return "never"
	}
	// Preserve native rule approvals, but never offer an unsandboxed retry or
	// a permissions grant that bypasses the host's exact filesystem boundary.
	return map[string]any{"granular": map[string]any{
		"sandbox_approval": false, "rules": true, "skill_approval": true,
		"mcp_elicitations": true, "request_permissions": false,
	}}
}
